'use strict';
// Same contract for the Windows bridge and user-granted browser directory handles.
window.projectAdapter=window.amagoDesktop?.project||(()=>{
let root,handles=new Map();const digest=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))).map(b=>b.toString(16).padStart(2,'0')).join('');
const attempt=fn=>async(...args)=>{try{return await fn(...args)}catch(e){return {error:e.name==='AbortError'?'Operação cancelada.':e.message}}};
const tree=async()=>{if(!root)throw Error('Abra uma pasta primeiro.');let count=0,truncated=false,warnings=0;const map=new Map();const visit=async(dir,base='',depth=0)=>{if(depth>12){truncated=true;return []}const entries=[];try{for await(const entry of dir.values())entries.push(entry)}catch{warnings++;return []}entries.sort((a,b)=>Number(b.kind==='directory')-Number(a.kind==='directory')||a.name.localeCompare(b.name));const out=[];for(const entry of entries){if(['.git','node_modules','.svn','.hg'].includes(entry.name)||entry.name.startsWith('.amago-write-'))continue;if(count++>=3000){truncated=true;break}const path=base?base+'/'+entry.name:entry.name;map.set(path,entry);const kind=entry.kind==='directory'?'directory':/\.(md|markdown)$/i.test(path)?'markdown':/\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(path)?'image':'file';const modified=kind!=='directory'?await entry.getFile().then(f=>new Date(f.lastModified).toISOString()).catch(()=>null):null;out.push({name:entry.name,path,kind,updated:modified,...(kind==='directory'?{children:await visit(entry,path,depth+1)}:{})})}return out};const entries=await visit(root);handles=map;return {name:root.name,root:root.name,entries,truncated,warnings}};
const read=async path=>{const h=handles.get(path);if(!h||!/(\.md|\.markdown)$/i.test(path))throw Error('Arquivo Markdown não encontrado.');const file=await h.getFile();if(file.size>5*1024*1024)throw Error('O limite para edição é 5 MB.');let body;try{body=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer())}catch{throw Error('Converta este arquivo para UTF-8.')} if(body.includes('\0'))throw Error('Converta este arquivo para UTF-8.');return {body,version:await digest(body),size:file.size,updated:new Date(file.lastModified).toISOString()}};
return {open:attempt(async()=>{if(!window.showDirectoryPicker)throw Error('Abra no aplicativo Windows ou em um navegador compatível, como Edge ou Chrome, para editar pastas locais.');const candidate=await window.showDirectoryPicker({mode:'readwrite'});root=candidate;return tree()}),tree:attempt(tree),read:attempt(read),save:attempt(async(path,body,version)=>{if(new TextEncoder().encode(body).length>5*1024*1024)throw Error('O limite para edição é 5 MB.');const current=await read(path);if(current.version!==version)return {conflict:true};const writable=await handles.get(path).createWritable();try{if((await read(path)).version!==version){await writable.abort();return {conflict:true}}await writable.write(body);await writable.close();return {saved:true,version:await digest(body)}}catch(e){await writable.abort().catch(()=>{});throw e}}),image:attempt(async path=>{const file=await handles.get(path).getFile();if(file.size>25*1024*1024)throw Error('O limite de prévia é 25 MB.');return {url:URL.createObjectURL(file),size:file.size}}),create:attempt(async(path,kind)=>{const parts=path.split('/');if(parts.some(p=>!p||p==='..'||p==='.'||/[\\:]/.test(p)))throw Error('Caminho inválido.');let dir=root;for(const part of parts.slice(0,-1))dir=await dir.getDirectoryHandle(part);const name=parts.at(-1);for await(const entry of dir.values())if(entry.name.toLowerCase()===name.toLowerCase())throw Error('Esse nome já existe.');if(kind==='directory')await dir.getDirectoryHandle(name,{create:true});else{if(!/\.(md|markdown)$/i.test(name))throw Error('Use a extensão .md.');await dir.getFileHandle(name,{create:true})}return {created:true}})};
})();
